import os
import torch

# ==========================================
# Global Configuration & Reproducibility
# ==========================================
SEED = 42
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
NUM_WORKERS = 4  # Number of data loading workers

# ==========================================
# File Paths & Directories
# ==========================================
INPUT_DIR = "./input"
METADATA_DIR = "./metadata"
WORKING_DIR = "./working"
CACHE_DIR = os.path.join(WORKING_DIR, "idea_10")

# Metadata paths generated by the metadata script
TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

# Submission output
SUBMISSION_PATH = "./submission/submission.csv"

# Ensure cache directory exists
os.makedirs(CACHE_DIR, exist_ok=True)

# ==========================================
# Data Processing Hyperparameters
# ==========================================
# The specific modalities used in the Tri-Stream architecture
# Note: T1w is excluded based on the TMSV-Net design description
MODALITIES = ["FLAIR", "T1wCE", "T2w"]

# Deterministic Data Expansion:
# We extract samples centered at these relative depths of the brain volume
EXPANSION_DEPTHS = [0.45, 0.50, 0.55]

# Input dimensions
# EfficientNet-B0 native resolution is typically 224x224.
# Using 256x256 preserves slightly more detail while remaining computationally efficient.
IMAGE_SIZE = (256, 256)

# Number of slices per slab (channels per stream)
# The architecture uses [z-1, z, z+1]
SLAB_DEPTH = 3

# ==========================================
# Model Hyperparameters
# ==========================================
MODEL_BACKBONE = "efficientnet_b0"
PRETRAINED = True
# High dropout rate for the fusion head as specified
DROP_RATE = 0.5
NUM_CLASSES = 1  # Binary classification (MGMT_value)

# ==========================================
# Training Hyperparameters
# ==========================================
# Batch size tailored for A100 40GB GPU with 3 parallel streams
BATCH_SIZE = 32

# Optimizer settings
LEARNING_RATE = 1e-4
WEIGHT_DECAY = 1e-2  # Aggressive regularization

# Training duration
EPOCHS = 15
EARLY_STOPPING_PATIENCE = 5

# Cross-validation
N_FOLDS = 5

# ==========================================
# Debugging & Development
# ==========================================
# Set DEBUG to True to run on a small subset of data for quick pipeline verification
DEBUG = False
DEBUG_SAMPLE_SIZE = 20
